update public.global_settings
set landing_content = jsonb_set(
  coalesce(landing_content, '{}'::jsonb),
  '{about}',
  '{"badge":"আমাদের সম্পর্কে","title":"বাংলাদেশের রিসেলারদের জন্য সম্পূর্ণ বিজনেস প্ল্যাটফর্ম","body":"Resell Seba একটি মাল্টি-টেন্যান্ট রিসেলিং প্ল্যাটফর্ম। আমাদের ভেরিফাইড মাস্টার ক্যাটালগ থেকে প্রোডাক্ট বেছে নিয়ে নিজের প্রফিট বসিয়ে লিস্ট করুন, নিজের ব্র্যান্ডেড স্টোর থেকে অর্ডার নিন — প্রোডাক্ট স্টক, প্যাকেজিং, কুরিয়ার বুকিং আর ডেলিভারি ফলোআপ আমরা সামলাই। আপনি শুধু মার্কেটিং আর সেলে ফোকাস করুন।","points":["ভেরিফাইড মাস্টার ক্যাটালগ — SEO রেডি প্রোডাক্ট কনটেন্ট, ছবি ও ডিটেইলস রেডিমেড","নিজের প্রফিট নিজেই ঠিক করুন — প্রোডাক্ট প্রাইস, ডেলিভারি ও প্যাকেজিং কস্ট আগেই পরিষ্কার","কাস্টম ডোমেইন ও স্টোর ডিজাইন — নিজের ব্র্যান্ড লোগো, কালার, OG ও ফেভিকন সেট করুন","Steadfast, Pathao ও CarryBee কুরিয়ার — বুকিং ও পার্সেল ট্র্যাকিং একই প্যানেলে","bKash, Nagad, Rocket সহ SSLCommerz ও EPS পেমেন্ট মেথড সাপোর্ট","Facebook Pixel/CAPI ও TikTok Events API — অ্যাডসের সঠিক ট্র্যাকিং","রিয়েল-টাইম ড্যাশবোর্ড — সেল, প্রফিট, কমিশন ও ডিউ পেমেন্ট রিপোর্ট","টিম ও স্টাফ পারমিশন কন্ট্রোল সহ সিকিউর অ্যাডমিন প্যানেল"]}'::jsonb
)
where id = 1;